package net.civeira.phylax.features.oauth.session.infrastructure.driver.rest;

import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.util.Base64;

import jakarta.enterprise.context.RequestScoped;
import jakarta.ws.rs.CookieParam;
import jakarta.ws.rs.GET;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.PathParam;
import jakarta.ws.rs.QueryParam;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.oauth.authentication.infrastructure.driver.html.OidcCookieManager;
import net.civeira.phylax.features.oauth.session.application.SessionStateService;

/**
 * OP iframe for OIDC Session Management; browser messages are checked against registered RP
 * origins.
 */
@Path("")
@RequestScoped
@RequiredArgsConstructor
public class SessionManagementController {
  private static final SecureRandom RANDOM = new SecureRandom();
  private final SessionStateService states;

  @GET
  @Path("oauth/openid/{tenant}/login-status-iframe")
  public Response iframe(@PathParam("tenant") String tenant) {
    byte[] random = new byte[24];
    RANDOM.nextBytes(random);
    String nonce = Base64.getUrlEncoder().withoutPadding().encodeToString(random);
    String path =
        "/oauth/openid/" + URLEncoder.encode(tenant, StandardCharsets.UTF_8) + "/session-check";
    String html = "<!doctype html><html><head><meta charset=\"utf-8\"></head><body>"
        + "<script nonce=\"" + nonce + "\">" + "addEventListener('message',async function(event){"
        + "if(typeof event.data!=='string')return;"
        + "const fields=event.data.split(' ');if(fields.length!==2)return;" + "const url=new URL('"
        + path + "',location.origin);" + "url.searchParams.set('client_id',fields[0]);"
        + "url.searchParams.set('origin',event.origin);"
        + "url.searchParams.set('session_state',fields[1]);"
        + "try{const r=await fetch(url,{credentials:'include',cache:'no-store'});"
        + "const result=r.ok?await r.text():'error';"
        + "event.source.postMessage(result,event.origin);"
        + "}catch(e){event.source.postMessage('error',event.origin);}});"
        + "</script></body></html>";
    return Response.ok(html).type("text/html;charset=UTF-8").header("Cache-Control", "no-store")
        .header("Referrer-Policy", "no-referrer")
        .header("Content-Security-Policy", "default-src 'none'; script-src 'nonce-" + nonce
            + "'; connect-src 'self'; base-uri 'none'")
        .build();
  }

  @GET
  @Path("oauth/openid/{tenant}/session-check")
  public Response check(@PathParam("tenant") String tenant,
      @CookieParam(OidcCookieManager.AUTH_SESSION_ID) String cookie,
      @QueryParam("client_id") String clientId, @QueryParam("origin") String origin,
      @QueryParam("session_state") String sessionState) {
    String status = states.check(tenant, cookie, clientId, origin, sessionState);
    return Response.ok(status).type("text/plain;charset=UTF-8").header("Cache-Control", "no-store")
        .header("X-Content-Type-Options", "nosniff").build();
  }
}
